<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Чем ориентировочная цена ГОЗ отличается от фиксированной?", "acceptedAnswer": {"@type": "Answer", "text": "Ориентировочную (уточняемую) цену применяют, когда при заключении контракта точно рассчитать затраты нельзя, и в ходе исполнения её переводят в фиксированную по фактическим затратам. Фиксированная цена окончательна и не меняется до конца поставки."}}, {"@type": "Question", "name": "Сколько видов цен на продукцию ГОЗ существует?", "acceptedAnswer": {"@type": "Answer", "text": "Три: ориентировочная (уточняемая) цена, фиксированная цена и цена, возмещающая издержки. Это закрытый перечень по статье 11 Федерального закона № 275-ФЗ."}}, {"@type": "Question", "name": "Чем ориентировочная цена отличается от фиксированной?", "acceptedAnswer": {"@type": "Answer", "text": "Ориентировочная цена — предварительная, она устанавливается, когда точно рассчитать затраты нельзя, и подлежит переводу в фиксированную. Фиксированная цена — твёрдая и не пересматривается в ходе исполнения контракта."}}, {"@type": "Question", "name": "Что такое «сравнимая цена» ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Это не вид цены, а метод её определения — обоснование стоимости сопоставлением с ценами на аналогичную или однородную продукцию. Результат всё равно оформляется как один из трёх видов цены."}}, {"@type": "Question", "name": "Когда применяется цена, возмещающая издержки?", "acceptedAnswer": {"@type": "Answer", "text": "Когда заранее достоверно неизвестны объём и состав работ. Заказчик возмещает исполнителю фактические обоснованные затраты и выплачивает прибыль; затем цена переводится в фиксированную."}}, {"@type": "Question", "name": "Какими нормами регулируются цены ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Виды цен закреплены в статье 11 Закона № 275-ФЗ, методы регулирования — в статье 10. Условия применения видов цен и методы расчёта установлены Постановлением Правительства РФ от 02.12.2017 № 1465."}}, {"@type": "Question", "name": "В какой срок ориентировочную цену переводят в фиксированную?", "acceptedAnswer": {"@type": "Answer", "text": "Фиксированную цену заказчик по согласованию с единственным поставщиком устанавливает не позднее чем за 2 месяца до окончания поставки продукции по завершении периода применения соответствующего вида цены."}}, {"@type": "Question", "name": "Какие методы определения цены предусмотрены Постановлением № 1465?", "acceptedAnswer": {"@type": "Answer", "text": "Анализ рыночных индикаторов, метод сравнимой цены, затратный метод, индексация базовой цены, индексация по статьям базовых затрат и индексация цены ранее поставленной продукции."}}, {"@type": "Question", "name": "Можно ли сразу применить затратный метод?", "acceptedAnswer": {"@type": "Answer", "text": "Нет, он применяется по остаточному принципу — если метод анализа рыночных индикаторов и метод сравнимой цены неприменимы и базовая цена ранее не формировалась."}}, {"@type": "Question", "name": "Влияет ли вид цены на казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Структура цены раскрывается и проверяется при сопровождении, а затраты должны проходить санкционирование. По ориентировочной цене особенно важно вести учёт так, чтобы при переводе в фиксированную затраты подтверждались."}}, {"@type": "Question", "name": "Кто поможет с обоснованием цены и сопровождением контракта ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Эту работу можно передать на аутсорсинг: эксперт помогает выбрать вид цены, обосновать расчёт, выстроить учёт и пройти казначейское сопровождение. Оставьте заявку — разберём ваш контракт."}}, {"@type": "Question", "name": "Что такое ориентировочная цена в гособоронзаказе?", "acceptedAnswer": {"@type": "Answer", "text": "Ориентировочная (уточняемая) цена — вид цены государственного контракта по гособоронзаказу, который применяют, когда точную цену определить заранее нельзя (статья 11 № 275-ФЗ). В ходе исполнения такая цена переводится в фиксированную по установленной методике; до перевода расчёты и прибыль считаются с учётом её ориентировочного характера."}}]}
